package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.io.*;
public class ImprovementChecks extends Instrumentation {
 interface Condition{boolean ok();}void await(Condition c)throws Exception{for(int i=0;i<240;i++){if(c.ok())return;Thread.sleep(50);}throw new AssertionError("Timed out");}void check(boolean b,String m){if(!b)throw new AssertionError(m);}public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->a.service!=null);PlaybackService p=a.service;
 runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.upcoming.clear();p.backlog.clear();p.repeat=p.repeatAll=false;p.index=0;p.queue.add(new Track("Z local","Test","demo","local"));p.queue.add(new Track("A remote","Test","testremote1","youtube"));p.queue.add(new Track("Other local","Test","demo","local"));p.play(0);});await(()->p.playing());runOnMainSync(()->p.seek(20000));await(()->p.position()>=19500);runOnMainSync(()->{p.pause(false);p.checkpoint();p.releasePlayer();p.onStartCommand(new Intent().setAction("play"),0,1);});await(()->p.playing());check(p.position()>=19000,"Notification restores saved position with no player");
 runOnMainSync(()->{a.render();Button fav=a.mini.findViewWithTag("nowFavorite");fav.performClick();check(p.current().favorite,"Now-playing favourite");a.prefs.edit().putInt("librarySort",5).apply();check(a.library.indices().get(2)==1,"Remote sorts below ready local tracks");int library=p.queue.size(),queued=p.upcoming.size();Recommendations.seed(p);check(p.queue.size()==library&&p.upcoming.size()==queued,"Recommendation seed does not enqueue or append");p.enqueue(p.queue.get(2),false);a.showQueue();QueueSheet sheet=(QueueSheet)a.queueRows;sheet.cards.get(p.queue.get(2)).performClick();});await(()->p.current()==p.queue.get(2)&&p.playing());
 runOnMainSync(()->{a.queueDialog.dismiss();p.clearUpcoming();p.pause(true);});File partial=new File(getTargetContext().getCacheDir(),"audio-download-testpart001");partial.mkdirs();File data=new File(partial,"test.part");try(FileOutputStream out=new FileOutputStream(data)){out.write(new byte[100]);}PartialDownloads.prune(getTargetContext(),"testpart002");check(data.length()==100,"Recent partial retained");partial.setLastModified(System.currentTimeMillis()-8L*86400000);PartialDownloads.prune(getTargetContext(),"testpart002");check(!partial.exists(),"Expired partial pruned");result.putString("result","PASS: notification resume without player, favourites, cached-ready sorting, queue row playback, recommendation seed side effects, partial retention/expiry");
 }catch(Throwable e){result.putString("failure",e.toString());}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
